import json

lines = open('ios_crash.ips').readlines()
crash = json.loads(''.join(lines[1:]))

# Check lastExceptionBacktrace structure
lebt = crash.get('lastExceptionBacktrace', None)
if lebt:
    if isinstance(lebt, list):
        frames = lebt
    elif isinstance(lebt, dict):
        frames = lebt.get('frames', [])
    else:
        frames = []

    dotnet_indices = {2,3,4,5,6,7}
    used_images = crash.get('usedImages', [])
    print('=== lastExceptionBacktrace .NET FRAMES ===')
    for fi, frame in enumerate(frames):
        img_idx = frame.get('imageIndex', -1)
        if img_idx in dotnet_indices:
            img = used_images[img_idx]
            addr = img['base'] + frame['imageOffset']
            print(f\"  #{fi} {img['name']} 0x{addr:x} (offset 0x{frame['imageOffset']:x})\")

# Also get all faulting thread frames for context
print('\n=== FULL FAULTING THREAD (first 10 + .NET) ===')
ft_idx = crash.get('faultingThread', 0)
ft = crash['threads'][ft_idx]
for fi, frame in enumerate(ft.get('frames', [])):
    img_idx = frame.get('imageIndex', -1)
    img = used_images[img_idx] if 0 <= img_idx < len(used_images) else None
    if img:
        addr = img['base'] + frame['imageOffset']
        if fi < 10 or img_idx in dotnet_indices or img_idx in (0,1):
            print(f\"  #{fi} [{img_idx}] {img['name']} 0x{addr:x}\")
